/**
 * Phase B round 3 (adopted from the re-review's accounting scratch test): F1 accounting under concurrency and a
 * switch-on/off differential.
 * <ul>
 * <li>Six threads drive builds, revalidating lookups that re-stamp (and ones that take today's path and submit
 * refreshes), Frontier-drift lookups that submit refreshes which replace logged variants, execution observations,
 * narrow, broad and hard evidence changes and log drops, under a budget that keeps dropping logs and evicting families.
 * After each phase (threads joined, refresh tasks idle): the read-log bytes equal the sum of the resident variants'
 * charged log bytes; the family bytes equal a recomputation without logs; the implementer's recomputation (families
 * with logs) equals the reported total; families + logs + reservations + doorkeeper fit the budget.</li>
 * <li>One seeded single-threaded script (builds, hits, Frontier drift with refreshes, observations, evidence changes)
 * run with the switch off and on: the same outcome, resident family set, eviction count and publication count after
 * every step.</li>
 * </ul>
 */
@Timeout(600)
class LmdbPlanCacheRevalidationAccountingTest {

	private static final int FAMILIES = 64;
	private static final int KEYS = 14;
	private static final int READS = 4;

	@TempDir
	Path directory;
	private String previousSwitch;
	private LmdbOperatorFeedbackStats stats;
	private final AtomicInteger sources = new AtomicInteger();
	private final AtomicLong refreshes = new AtomicLong();

	@BeforeEach
	void rememberSwitch() throws Exception {
		previousSwitch = System.getProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY);
		stats = LmdbPlanCacheRevalidationTest.feedback(directory);
	}

	@AfterEach
	void restoreSwitch() {
		if (previousSwitch == null) {
			System.clearProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY);
		} else {
			System.setProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY, previousSwitch);
		}
	}

	// ------------------------------------------------------------------------------------------ concurrent stress

	@ParameterizedTest(name = "cores={0} logs={1}")
	@CsvSource({ "5,3,false", "10,4,true", "16,2,true" })
	void concurrentChargingPathsKeepTheLogBytesAndTheFamilyBytesEqualToARecomputationAndWithinTheBudget(int cores,
			int logs, boolean refreshesFit) throws Exception {
		System.setProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY, "true");
		long[] sizes = sizes();
		long core = sizes[0];
		long log = sizes[1];
		long doorkeeper = LmdbPlanDecisionCache.doorkeeperBytes(FAMILIES);
		long budget = doorkeeper + cores * core + logs * log;
		refreshes.set(0L);
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILIES, 4, budget);
		ExecutorService workers = Executors.newFixedThreadPool(6);
		List<String> violations = new ArrayList<>();
		List<String> failures = new ArrayList<>();
		AtomicLong operations = new AtomicLong();
		try {
			for (int phase = 0; phase < 8; phase++) {
				List<Future<?>> futures = new ArrayList<>();
				for (int thread = 0; thread < 6; thread++) {
					long seed = 7919L * phase + thread;
					futures.add(workers.submit(() -> {
						Random random = new Random(seed);
						for (int op = 0; op < 150; op++) {
							try {
								randomOperation(cache, random);
								operations.incrementAndGet();
							} catch (RuntimeException | Error failure) {
								synchronized (failures) {
									if (failures.size() < 10) {
										failures.add(failure.toString());
									}
								}
							}
						}
					}));
				}
				for (Future<?> future : futures) {
					future.get(300, TimeUnit.SECONDS);
				}
				awaitRefreshesIdle(cache);
				check("phase " + phase, cache, budget, doorkeeper, violations);
			}
			LmdbPlanDecisionCache.Statistics statistics = cache.decisionCacheForTest().statistics();
			System.out.println("[revalidation-accounting] cores=" + cores + " budget=" + budget + " core=" + core
					+ " log=" + log
					+ " operations=" + operations.get() + " refreshesExecuted=" + refreshes.get() + " families="
					+ statistics.families() + " evictions=" + statistics.evictions() + " publications="
					+ statistics.publications() + " stale=" + statistics.stalePublications() + " hits="
					+ statistics.hits() + "\n  revalidation=" + statistics.revalidation() + "\n  failures=" + failures
					+ "\n  violations=" + violations);
			Map<String, Long> dropped = statistics.revalidation().logsDropped();
			assertTrue(statistics.evictions() > 0L, "COVERAGE_PREREQUISITE: families were evicted");
			assertTrue(dropped.getOrDefault(LmdbPlanCacheRevalidation.DROPPED_FOR_SLACK, 0L) > 0L,
					"COVERAGE_PREREQUISITE: logs were dropped for the slack: " + dropped);
			assertTrue(statistics.revalidation().restamps() > 0L, "COVERAGE_PREREQUISITE: re-stamps happened");
			// At five family cores a refresh's reservation never fits next to the resident families.
			assertTrue(!refreshesFit || refreshes.get() > 0L, "COVERAGE_PREREQUISITE: refreshes ran");
			assertEquals(List.of(), failures, "operations must not fail");
			assertEquals(List.of(), violations);
		} finally {
			workers.shutdownNow();
			cache.close();
		}
	}

	private void randomOperation(LmdbPipelinePlanCache cache, Random random) {
		int key = random.nextInt(KEYS);
		boolean ranked = key % 2 == 0;
		int choice = random.nextInt(100);
		LmdbPlanDecisionCache decisions = cache.decisionCacheForTest();
		if (choice < 30) {
			request(cache, key, ranked, LmdbPlanCacheRevalidationTest.learned(17L, 3L), null);
		} else if (choice < 50) {
			request(cache, key, ranked, LmdbPlanCacheRevalidationTest.learned(17L, 30L + random.nextInt(4)),
					new LmdbPlanCacheRevalidationTest.StubValidator(LmdbPlanningReadLog.Verdict.IDENTICAL));
		} else if (choice < 58) {
			request(cache, key, ranked, LmdbPlanCacheRevalidationTest.learned(17L, 30L + random.nextInt(4)),
					new LmdbPlanCacheRevalidationTest.StubValidator(LmdbPlanningReadLog.Verdict.CHANGED,
							LmdbPlanningReadLog.EXACT_FACT));
		} else if (choice < 72) {
			// Frontier drift: today's path (stale serve with refresh for a ranked family).
			request(cache, key, ranked, LmdbPlanCacheRevalidationTest.learned(17L, 20L + random.nextInt(2), 3L, 7L,
					0L, true), new LmdbPlanCacheRevalidationTest.StubValidator(LmdbPlanningReadLog.Verdict.IDENTICAL));
		} else if (choice < 86) {
			observe(cache, random);
		} else if (choice < 90) {
			decisions.markEvidenceChanged(new LmdbPlanDecisionCache.EvidenceChange(
					new LmdbPlanDecisionCache.EvidenceDependency(LmdbPlanDecisionCache.EvidenceKind.LEO, "global", 1L),
					false, false));
		} else if (choice < 92) {
			decisions.markEvidenceChanged(new LmdbPlanDecisionCache.EvidenceChange(
					new LmdbPlanDecisionCache.EvidenceDependency(LmdbPlanDecisionCache.EvidenceKind.LEO, "global", 1L),
					random.nextBoolean(), true));
		} else if (choice < 94) {
			decisions.dropReadLogsForTest();
		} else {
			request(cache, key, ranked, LmdbPlanCacheRevalidationTest.learned(17L, 3L), null);
		}
	}

	private void observe(LmdbPipelinePlanCache cache, Random random) {
		Map<LmdbPlanDecisionCache.PlanFamilyKey, LmdbPlanDecisionCache.FamilyVersion> resident = cache
				.decisionCacheForTest()
				.residentFamiliesForTest();
		if (resident.isEmpty()) {
			return;
		}
		List<Map.Entry<LmdbPlanDecisionCache.PlanFamilyKey, LmdbPlanDecisionCache.FamilyVersion>> entries = new ArrayList<>(
				resident.entrySet());
		var entry = entries.get(random.nextInt(entries.size()));
		LmdbPlanDecisionCache.PlanVariant variant = entry.getValue().dispatcher().variants().get(0);
		cache.observeExecution(new LmdbPlanDecisionCache.ExecutionObservation(entry.getKey(), variant.variantId(),
				variant.champion().version(), true, false, random.nextDouble() * 4.0d, 1024L, random.nextInt(40) == 0,
				false));
	}

	private boolean request(LmdbPipelinePlanCache cache, int key, boolean ranked, LmdbPipelinePlanCache.Context context,
			LmdbPlanCacheRevalidation.Validator validator) {
		QueryRoot source = LmdbPlanCacheRevalidationTest.query("_anon_x" + sources.incrementAndGet(),
				"urn:stress:" + key);
		return cache.getOrComputePlan(source, context, context::revision, () -> {
			for (int read = 0; read < READS; read++) {
				LmdbPlanCacheRevalidationTest.logicalRead(stats,
						LmdbPlanCacheRevalidationTest.logical("stress-" + key + "-" + read));
			}
			source.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
			if (!ranked) {
				source.setStringMetricPlanned("optimizer.cascadesCostComparisonCompleteness", "UNAVAILABLE_COST");
				return new LmdbPipelinePlanCache.PlanComputation(source,
						LmdbPlanCacheRevalidationTest.replayOnlySummary(), null);
			}
			return new LmdbPipelinePlanCache.PlanComputation(source, LmdbPlanCacheRevalidationTest.rankedSummary(),
					refreshWork(key, context));
		}, () -> Long.MIN_VALUE, validator).cacheHit();
	}

	/** A refresh that publishes a promoted candidate planned at {@code at}; each execution a new physical plan. */
	private LmdbPlanDecisionCache.DetachedRefreshWork refreshWork(int key, LmdbPipelinePlanCache.Context at) {
		TupleExpr detached = LmdbPlanCacheRevalidationTest.query("_anon_r" + key, "urn:stress:" + key);
		return new LmdbPlanDecisionCache.DetachedRefreshWork() {
			@Override
			public LmdbPlanDecisionCache.RefreshComputation execute() {
				long serial = refreshes.incrementAndGet();
				TupleExpr refreshed = detached.clone();
				refreshed.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
				LmdbPlanDecisionCache.EvidenceSnapshot evidence = LmdbPipelinePlanCache
						.evidence(at.revision().planningRevisions());
				return new LmdbPlanDecisionCache.RefreshComputation(evidence, evidence, refreshed,
						"refreshed-physical-" + (serial % 3),
						new LmdbPlanDecisionCache.EstimatedCostInterval(0.5d, 0.5d),
						new LmdbPlanDecisionCache.EstimatedCostInterval(1.0d, 1.0d),
						LmdbPipelinePlanCache.certificate(LmdbPlanCacheRevalidationTest.rankedSummary(),
								evidence.globalEpoch()),
						LmdbPlanDecisionCache.PlanStabilityEnvelope.exact(evidence), 1024L, 1L, true, this);
			}

			@Override
			public long retainedBytes() {
				return 0L;
			}
		};
	}

	private static void awaitRefreshesIdle(LmdbPipelinePlanCache cache) {
		LmdbPlanCacheRevalidationLogDropTest.awaitRefreshesIdle(cache);
	}

	private static void check(String label, LmdbPipelinePlanCache cache, long budget, long doorkeeper,
			List<String> violations) {
		LmdbPlanDecisionCache decisions = cache.decisionCacheForTest();
		LmdbPlanDecisionCache.Statistics statistics = decisions.statistics();
		long logs = statistics.revalidation().readLogBytes();
		long total = statistics.retainedBytes();
		long families = total - logs;
		long charged = chargedLogBytes(decisions);
		long recomputedFamilies = familyBytesWithoutLogs(decisions);
		long implementerRecomputation = LmdbPlanCacheRevalidationTest.recomputedCharges(decisions);
		long reserved = decisions.reservedBytesForTest();
		if (logs != charged) {
			violations.add(label + ": readLogBytes=" + logs + " but resident charged logs=" + charged);
		}
		if (families != recomputedFamilies) {
			violations.add(label + ": family bytes=" + families + " but recomputed=" + recomputedFamilies);
		}
		if (implementerRecomputation != total) {
			violations.add(label + ": total=" + total + " but implementer recomputation=" + implementerRecomputation);
		}
		if (total + reserved + doorkeeper > budget) {
			violations.add(label + ": total " + total + " + reserved " + reserved + " + doorkeeper " + doorkeeper
					+ " > budget " + budget);
		}
		if (logs < 0L) {
			violations.add(label + ": negative log bytes " + logs);
		}
	}

	static long chargedLogBytes(LmdbPlanDecisionCache decisions) {
		long bytes = 0L;
		for (LmdbPlanDecisionCache.FamilyVersion version : decisions.residentFamiliesForTest().values()) {
			for (LmdbPlanDecisionCache.PlanVariant variant : version.dispatcher().variants()) {
				if (variant.keepsReadLog()) {
					bytes += variant.readLogBasis().chargedBytes();
				}
			}
		}
		return bytes;
	}

	/** The implementer's recomputation (LmdbPlanCacheRevalidationTest#recomputedCharges) without the bases. */
	static long familyBytesWithoutLogs(LmdbPlanDecisionCache decisions) {
		long total = 0L;
		for (Map.Entry<LmdbPlanDecisionCache.PlanFamilyKey, LmdbPlanDecisionCache.FamilyVersion> family : decisions
				.residentFamiliesForTest()
				.entrySet()) {
			FactorCostCacheKey.ProviderRetainedMemory ledger = new FactorCostCacheKey.ProviderRetainedMemory();
			long fixed = LmdbPipelinePlanCache.ENTRY_OBJECT_BYTES - LmdbPipelinePlanCache.VERSION_OBJECT_BYTES;
			Set<Long> counted = new HashSet<>();
			List<LmdbPlanDecisionCache.PlanVariant> variants = family.getValue().dispatcher().variants();
			fixed += (variants.size() - 1L) * LmdbPipelinePlanCache.VARIANT_OBJECT_BYTES;
			for (LmdbPlanDecisionCache.PlanVariant variant : variants) {
				fixed += variant.challengerPosteriors().size() * LmdbPipelinePlanCache.CHALLENGER_POSTERIOR_BYTES;
				List<LmdbPlanDecisionCache.PlanVersion> versions = new ArrayList<>();
				versions.add(variant.champion());
				versions.addAll(variant.challengers());
				versions.addAll(variant.rollbackVersions());
				for (LmdbPlanDecisionCache.PlanVersion version : versions) {
					if (!counted.add(version.version())) {
						continue;
					}
					((LmdbPlanDecisionCache.ExactTupleRecipe) version.physicalRecipe()).accountTo(ledger);
					fixed += LmdbPipelinePlanCache.VERSION_OBJECT_BYTES;
					if (version.detachedRefreshWork() != null) {
						version.detachedRefreshWork().accountCacheIdentity(ledger);
						fixed += version.detachedRefreshWork().retainedBytes();
					}
				}
			}
			ledger.account(family.getValue().semanticDependencies());
			ledger.account(family.getKey());
			for (LmdbPlanDecisionCache.ExactInvocationKey exact : family.getValue().exactAliases().keySet()) {
				ledger.account(exact);
			}
			fixed += Math.max(0, family.getValue().exactAliases().size() - 1)
					* LmdbPipelinePlanCache.APPENDED_ALIAS_BYTES;
			total += fixed + ledger.bytes();
		}
		return total;
	}

	/** One ranked family's bytes without its log and its log's charge, on an unconstrained cache. */
	private long[] sizes() {
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILIES, 1, 1L << 30);
		try {
			request(cache, 0, true, LmdbPlanCacheRevalidationTest.learned(17L, 3L), null);
			LmdbPlanDecisionCache.FamilyVersion family = cache.decisionCacheForTest()
					.residentFamiliesForTest()
					.values()
					.iterator()
					.next();
			long charged = family.dispatcher().variants().get(0).readLogBasis().chargedBytes();
			assertTrue(charged > 0L, "COVERAGE_PREREQUISITE: the log is charged");
			return new long[] { family.retainedBytes(), charged };
		} finally {
			cache.close();
		}
	}

	// ------------------------------------------------------------------------------------------ differential

	@ParameterizedTest(name = "cores={0}")
	@ValueSource(ints = { 4, 9 })
	void theSameScriptGivesTheSameDecisionsWithTheSwitchOffAndOn(int cores) throws Exception {
		System.setProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY, "true");
		long[] sizes = sizes();
		long budget = LmdbPlanDecisionCache.doorkeeperBytes(FAMILIES) + cores * sizes[0] + sizes[1] * 3L / 2L;
		List<String> off = script(false, budget);
		List<String> on = script(true, budget);
		System.out
				.println("[revalidation-differential] cores=" + cores + " refreshes(on)=" + refreshes.get() + " steps="
						+ off.size() + " budget=" + budget + "\n  lastOff="
						+ off.get(off.size() - 1) + "\n  lastOn =" + on.get(on.size() - 1));
		int firstDifference = -1;
		for (int step = 0; step < Math.min(off.size(), on.size()); step++) {
			if (!off.get(step).equals(on.get(step))) {
				firstDifference = step;
				break;
			}
		}
		String context = firstDifference < 0 ? ""
				: " first difference at step " + firstDifference + ": off=" + off.get(firstDifference) + " on="
						+ on.get(firstDifference);
		assertTrue(off.stream().anyMatch(line -> line.contains("evictions=1")),
				"COVERAGE_PREREQUISITE: the script evicts");
		assertEquals(off, on, "decisions differ:" + context);
	}

	private List<String> script(boolean validation, long budget) throws Exception {
		System.setProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY, Boolean.toString(validation));
		refreshes.set(0L);
		// Same source names in both runs: an anonymous name is part of the charged structural key.
		sources.set(1_000_000);
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILIES, 4, budget);
		Random random = new Random(20261111L);
		List<String> trace = new ArrayList<>();
		try {
			for (int step = 0; step < 400; step++) {
				int key = random.nextInt(9);
				boolean ranked = key % 2 == 0;
				int choice = random.nextInt(100);
				String outcome;
				if (choice < 55) {
					outcome = "build:" + key + ":" + outcome(cache, key, ranked,
							LmdbPlanCacheRevalidationTest.learned(17L, 3L));
				} else if (choice < 75) {
					outcome = "frontier:" + key + ":" + outcome(cache, key, ranked,
							LmdbPlanCacheRevalidationTest.learned(17L, 20L, 3L, 7L, 0L, true));
				} else if (choice < 90) {
					observeDeterministically(cache, random);
					outcome = "observe";
				} else if (choice < 96) {
					cache.decisionCacheForTest()
							.markEvidenceChanged(new LmdbPlanDecisionCache.EvidenceChange(
									new LmdbPlanDecisionCache.EvidenceDependency(
											LmdbPlanDecisionCache.EvidenceKind.LEO, "global", 1L),
									false, false));
					outcome = "suspect";
				} else {
					cache.decisionCacheForTest()
							.markEvidenceChanged(new LmdbPlanDecisionCache.EvidenceChange(
									new LmdbPlanDecisionCache.EvidenceDependency(
											LmdbPlanDecisionCache.EvidenceKind.LEO, "global", 1L),
									random.nextBoolean(), true));
					outcome = "broad";
				}
				awaitRefreshesIdle(cache);
				LmdbPlanDecisionCache.Statistics statistics = cache.decisionCacheForTest().statistics();
				long logs = statistics.revalidation().readLogBytes();
				trace.add(step + " " + outcome + " families=" + residentKeys(cache) + " evictions="
						+ statistics.evictions() + " publications=" + statistics.publications() + " stale="
						+ statistics.stalePublications() + " hits=" + statistics.hits() + " familyBytes="
						+ (statistics.retainedBytes() - logs));
			}
			return trace;
		} finally {
			cache.close();
		}
	}

	private String outcome(LmdbPipelinePlanCache cache, int key, boolean ranked,
			LmdbPipelinePlanCache.Context context) {
		QueryRoot source = LmdbPlanCacheRevalidationTest.query("_anon_d" + sources.incrementAndGet(),
				"urn:stress:" + key);
		LmdbPipelinePlanCache.Result result = cache.getOrComputePlan(source, context, context::revision, () -> {
			for (int read = 0; read < READS; read++) {
				LmdbPlanCacheRevalidationTest.logicalRead(stats,
						LmdbPlanCacheRevalidationTest.logical("stress-" + key + "-" + read));
			}
			source.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
			if (!ranked) {
				source.setStringMetricPlanned("optimizer.cascadesCostComparisonCompleteness", "UNAVAILABLE_COST");
				return new LmdbPipelinePlanCache.PlanComputation(source,
						LmdbPlanCacheRevalidationTest.replayOnlySummary(), null);
			}
			return new LmdbPipelinePlanCache.PlanComputation(source, LmdbPlanCacheRevalidationTest.rankedSummary(),
					refreshWork(key, LmdbPlanCacheRevalidationTest.learned(17L, 3L)));
		}, () -> Long.MIN_VALUE,
				new LmdbPlanCacheRevalidationTest.StubValidator(LmdbPlanningReadLog.Verdict.IDENTICAL));
		TupleExpr plan = result.plan();
		return result.cacheHit() + "/" + plan.getStringMetricPlanned("optimizer.planCacheLookupOutcome") + "/"
				+ plan.getStringMetricPlanned("optimizer.planCacheRefreshReason");
	}

	/** An observation of the resident family with the smallest key, chosen by the random stream. */
	private static void observeDeterministically(LmdbPipelinePlanCache cache, Random random) {
		Map<LmdbPlanDecisionCache.PlanFamilyKey, LmdbPlanDecisionCache.FamilyVersion> resident = cache
				.decisionCacheForTest()
				.residentFamiliesForTest();
		int pick = random.nextInt(9);
		double residual = random.nextDouble() * 4.0d;
		boolean blocked = random.nextInt(20) == 0;
		for (Map.Entry<LmdbPlanDecisionCache.PlanFamilyKey, LmdbPlanDecisionCache.FamilyVersion> entry : resident
				.entrySet()) {
			LmdbPlanDecisionCache.PlanVariant variant = entry.getValue().dispatcher().variants().get(0);
			if (("urn:stress:" + pick).equals(predicate(variant))) {
				cache.observeExecution(new LmdbPlanDecisionCache.ExecutionObservation(entry.getKey(),
						variant.variantId(), variant.champion().version(), true, false, residual, 1024L, blocked,
						false));
				return;
			}
		}
	}

	private static String residentKeys(LmdbPipelinePlanCache cache) {
		Set<String> keys = new TreeSet<>();
		for (LmdbPlanDecisionCache.FamilyVersion version : cache.decisionCacheForTest()
				.residentFamiliesForTest()
				.values()) {
			for (LmdbPlanDecisionCache.PlanVariant variant : version.dispatcher().variants()) {
				keys.add(predicate(variant) + "@" + variant.qualityState() + "/" + version.semanticValidity() + "/v"
						+ variant.challengers().size() + "c" + variant.rollbackVersions().size() + "r");
			}
		}
		return keys.toString();
	}

	private static String predicate(LmdbPlanDecisionCache.PlanVariant variant) {
		TupleExpr plan = variant.champion().materialize();
		TupleExpr arg = plan instanceof QueryRoot root ? root.getArg() : plan;
		if (arg instanceof Projection projection && projection.getArg() instanceof StatementPattern pattern) {
			return pattern.getPredicateVar().getValue().stringValue();
		}
		return "?";
	}
}
